        //municipality.style("fill", "url(#"+patternID+")");
        //municipality.style("fill", scwin.colorScale1(data[i].value));
    }
}
scwin.mapchart2_onbeforemapchange = function(info) {
    if (info.newMapCode.length >= 2) {
        return false; // 지도 확장기능 사용하지 않음 
    }
}
scwin.mapchart2_csvHandler = function(svg, data, projection) {
    for (var i = 0; i < data.length; i++) {
        var municipality = d3.select("#" + this.id + "_map").select(".municipality.c" + data[i].code);
        municipality.style("fill", scwin.colorScale2(data[i].value));
    }
}
scwin.mapchart3_onbeforemapchange = function(info) {
    if (info.newMapCode.length >= 2) {
        return false; // 지도 확장기능 사용하지 않음 
    }
}
scwin.mapchart3_csvHandler = function(svg, data, projection) {
    for (var i = 0; i < data.length; i++) {
        var municipality = d3.select("#" + this.id + "_map").select(".municipality.c" + data[i].code);
        municipality.style("fill", scwin.colorScale3(data[i].value));
    }
}
scwin.setTooltip = function(str1, str2) {
    return "test";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. heatmap_WSQ-345_(WSQ-2279).xml 실행한다.
    //1. Run heatmap_WSQ-345_ (WSQ-2279) .xml.
    //Test step 2. 실행화면에서 ctrl+우클릭 > 소스보기에서  dataMapRatio_level0 찾아 검색한다.
    //2. On the Run screen, find and search for dataMapRatio_level0 in the ctrl + right-click> Source view.
    //Verify 2. dataMapRatio_level0 값이 검색되어진다.
    //2. The dataMapRatio_level0 value is retrieved.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('mapchart1').getAttribute('dataMapRatio_level0') == 'simp01'", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 다시 소스에서 dataMapRatio 찾아 검색한다.
    //3. Retrieve dataMapRatio from the source and search again.
    //Verify 3. dataMapRatio 값은 검색되어지지 않는다.
    //3. The dataMapRatio value is not retrieved.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('mapchart1').getAttribute('dataMapRatio') == undefined", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

